   FrameLayout frame=new FrameLayout(getContext());frame.setBackground(UiStyle.shape(getContext(),UiStyle.SUBDUED,UiStyle.RADIUS_BADGE));ImageView image=new ImageView(getContext());image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackground(UiStyle.shape(getContext(),UiStyle.SUBDUED,UiStyle.RADIUS_BADGE));image.setClipToOutline(true);frame.addView(image,new FrameLayout.LayoutParams(-1,height));CreatorUi.this.image(url,image);
   if(play){TextView icon=text("▶",20,Color.WHITE);icon.setGravity(Gravity.CENTER);icon.setBackground(UiStyle.shape(getContext(),0x99000000,UiStyle.RADIUS_PILL));frame.addView(icon,new FrameLayout.LayoutParams(px(38),px(38),Gravity.CENTER));}
   return frame;
